package hagrid.core.config;
import java.util.*;
/** Explicit opt-in section configuration. */
public record SectionSettings(Optional<Double> maxSpanMeters, Optional<String> haltCatalogFile, boolean fastRegret, Optional<String> hagridInputsFile) {
 public SectionSettings(Optional<Double> maxSpanMeters,Optional<String> haltCatalogFile,boolean fastRegret){this(maxSpanMeters,haltCatalogFile,fastRegret,Optional.empty());}
 public SectionSettings(Optional<Double> maxSpanMeters,Optional<String> haltCatalogFile){this(maxSpanMeters,haltCatalogFile,false);}
 public SectionSettings {Objects.requireNonNull(maxSpanMeters);Objects.requireNonNull(haltCatalogFile);Objects.requireNonNull(hagridInputsFile);if(haltCatalogFile.isPresent()&&hagridInputsFile.isPresent())throw new IllegalArgumentException("Choose HAGRID inputs or a prepared halt catalog, not both");if(maxSpanMeters.isPresent()!=(haltCatalogFile.isPresent()||hagridInputsFile.isPresent()))throw new IllegalArgumentException("Section span requires routing.sectionHagridInputs or routing.haltCatalogFile");if(fastRegret && maxSpanMeters.isEmpty())throw new IllegalArgumentException("routing.sectionFastRegret requires section routing");}
 public static boolean contains(String key){return key.equals("routing.sectionAllowStreetCrossing")||key.equals("routing.sectionUnknownTurnPolicy")||key.equals("routing.sectionHagridInputs")||key.equals("routing.sectionMaxSpanMeters")||key.equals("routing.haltCatalogFile")||key.equals("routing.sectionFastRegret")||key.equals("routing.sectionEvidenceConfig")||key.equals("routing.sectionEvidenceTool")||key.equals("routing.sectionEvidencePython")||key.equals("routing.sectionEvidenceTimeoutSeconds");}
 public static void validate(String key,String value){if(key.equals("routing.sectionUnknownTurnPolicy")){if(!Set.of("STRICT","NETWORK_REVERSAL").contains(value))throw new IllegalArgumentException("Unknown section turn policy: "+value);}else if(key.equals("routing.sectionMaxSpanMeters")){double n=Double.parseDouble(value);if(!Double.isFinite(n)||n<=0)throw new IllegalArgumentException("section span must be positive and finite");}else if(key.equals("routing.haltCatalogFile")||key.equals("routing.sectionHagridInputs")){if(value==null||value.isBlank())throw new IllegalArgumentException("halt catalog path is blank");}else if(key.equals("routing.sectionEvidenceConfig")){if(value==null||value.isBlank())throw new IllegalArgumentException("section evidence config path is blank");}else if(key.equals("routing.sectionEvidenceTool")||key.equals("routing.sectionEvidencePython")){if(value==null||value.isBlank())throw new IllegalArgumentException("section evidence executable path is blank");}else if(key.equals("routing.sectionEvidenceTimeoutSeconds")){if(Long.parseLong(value)<=0)throw new IllegalArgumentException("section evidence timeout must be positive");}else if(key.equals("routing.sectionFastRegret")||key.equals("routing.sectionAllowStreetCrossing")){if(!"true".equals(value)&&!"false".equals(value))throw new IllegalArgumentException("routing.sectionFastRegret must be true or false");}else throw new IllegalArgumentException("unknown section setting");}
 public static SectionSettings from(Map<String,String> values){values.forEach((k,v)->{if(contains(k))validate(k,v);});return new SectionSettings(Optional.ofNullable(values.get("routing.sectionMaxSpanMeters")).map(Double::valueOf),Optional.ofNullable(values.get("routing.haltCatalogFile")),Boolean.parseBoolean(values.getOrDefault("routing.sectionFastRegret","false")),Optional.ofNullable(values.get("routing.sectionHagridInputs")));}
 public boolean enabled(){return maxSpanMeters.isPresent();}
}
